<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {setUser,safeNext} from '../auth'
const route=useRoute(),router=useRouter(),register=computed(()=>route.path==='/register')
const username=ref(''),password=ref(''),confirmation=ref(''),invite=ref(''),busy=ref(false),error=ref(''),show=ref(false)
watch(register,()=>{error.value='';password.value='';confirmation.value='';show.value=false})
async function submit(){
 if(busy.value)return
 error.value=''
 if(register.value&&password.value!==confirmation.value){error.value='两次输入的密码不一致';return}
 busy.value=true
 try{
  const response=await fetch('/api/auth/'+(register.value?'register':'login'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value,invite:invite.value.trim()})})
  const data=await response.json().catch(()=>null)
  if(!response.ok||!data?.user){error.value=typeof data?.message==='string'&&data.message.trim()?data.message:'无法连接服务，请稍后重试';return}
  setUser(data.user);password.value='';confirmation.value='';await router.replace(safeNext(route.query.next))
 }catch{error.value='无法连接服务，请稍后重试'}finally{busy.value=false}
}
</script>
<template><main class="auth-page"><section class="auth-story"><div class="auth-brand">yangbin <span>AI</span></div><div class="story-copy"><div class="eyebrow">YOUR PERSONAL AI WORKSPACE</div><h1>把想法<br>变成下一步。</h1><p>从自然语言对话、知识库检索到端到端代码修复，你的个人 AI Agent 工作台。</p><div class="story-tags"><span>64M 智能路由</span><span>Coding Agent</span><span>知识库 RAG</span><span>MCP 生态</span></div></div><small>可观测、可审阅、可回退的个人智能体工作空间。</small></section><section class="auth-form-wrap"><div class="auth-form"><span class="auth-kicker">{{register?'INVITATION ONLY':'WELCOME BACK'}}</span><h2>{{register?'创建你的账号':'欢迎回来'}}</h2><p class="auth-description">{{register?'使用管理员提供的邀请码，开启你的个人工作台。':'登录后，继续你的对话、知识库和计划。'}}</p><div v-if="error" class="auth-error" role="alert">{{error}}</div><div v-if="route.query.changed" class="auth-success">密码已更新，请重新登录。</div><form @submit.prevent="submit"><label>用户名<input v-model="username" autocomplete="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_-]{3,32}" placeholder="字母、数字、下划线或短横线" :disabled="busy"></label><label>密码<div class="password-field"><input v-model="password" aria-label="密码" :type="show?'text':'password'" :autocomplete="register?'new-password':'current-password'" required :minlength="register?10:1" maxlength="128" :placeholder="register?'至少 10 个字符':'输入密码'" :disabled="busy"><button type="button" @click="show=!show" :aria-label="show?'隐藏密码':'显示密码'">{{show?'隐藏':'显示'}}</button></div></label><template v-if="register"><label>确认密码<input v-model="confirmation" type="password" autocomplete="new-password" required minlength="10" maxlength="128" :disabled="busy"></label><label>邀请码<input v-model="invite" required maxlength="100" autocomplete="off" placeholder="向管理员获取邀请码" :disabled="busy"></label></template><button class="auth-submit" :disabled="busy">{{busy?'正在处理…':register?'注册并进入工作台':'登录'}}</button></form><p class="auth-switch">{{register?'已经有账号？':'还没有账号？'}} <RouterLink :to="{path:register?'/login':'/register',query:route.query.next?{next:route.query.next}:{}}">{{register?'去登录':'使用邀请码注册'}}</RouterLink></p><p class="auth-switch"><RouterLink to="/download" data-testid="desktop-download-entry">下载 Windows 客户端 ↗</RouterLink></p><p class="auth-note">{{register?'邀请码可能有次数和有效期限制，注册后无法查看其他用户的私有资料。':'忘记密码请联系管理员。原有账号可使用之前的用户名与口令登录。'}}</p></div></section></main></template>
<style scoped>
.auth-page{min-height:100dvh;display:grid;grid-template-columns:1fr 1fr;background:var(--yb-bg-canvas);color:var(--yb-ink)}
.auth-story{position:relative;isolation:isolate;overflow:hidden;padding:44px 10%;background:radial-gradient(ellipse at 15% 85%,#29376a80,transparent 60%),radial-gradient(ellipse at 90% 15%,#324a874a,transparent 50%),#10172d;display:flex;flex-direction:column;color:#cbd5e1;min-height:100dvh}
.auth-story::after{content:'';position:absolute;z-index:-1;width:620px;height:620px;border:1px solid #ffffff07;border-radius:50%;right:-420px;bottom:-80px;box-shadow:0 0 0 80px #ffffff02,0 0 0 160px #ffffff02}
.auth-brand{font-size:26px;letter-spacing:-1px;font-weight:750;color:white;display:flex;align-items:center;gap:9px}
.auth-brand span{color:#c7d2fe;font-size:12px;letter-spacing:.3px;border:1px solid #ffffff1f;background:#ffffff0a;padding:4px 7px;border-radius:var(--yb-radius-sm)}
.story-copy{margin:auto 0;padding:80px 0;max-width:450px}.eyebrow{font-size:10px;letter-spacing:2.5px;color:#a5b4db;font-weight:600}
.story-copy h1{font-size:clamp(42px,4.4vw,64px);line-height:1.25;letter-spacing:-2px;font-weight:650;color:#fff;margin:25px 0 28px}
.story-copy p{font-size:15px;line-height:2;color:#b5c0d7;max-width:385px}.story-tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:35px}.story-tags span{font-size:11px;white-space:nowrap;border:1px solid #c7d2fe25;background:#c7d2fe08;border-radius:var(--yb-radius-pill);padding:7px 11px;color:#d6def2}.auth-story small{font-size:11px;line-height:1.8;color:#96a4c0}
.auth-form-wrap{display:flex;align-items:center;justify-content:center;padding:45px 30px}.auth-form{width:100%;max-width:410px;background:var(--yb-bg-surface);border:1px solid var(--yb-border);border-radius:var(--yb-radius-lg);padding:32px;box-shadow:var(--yb-shadow-md)}
.auth-kicker{font-size:10px;letter-spacing:2px;font-weight:700;color:var(--yb-ink-muted)}.auth-form h2{font-size:30px;margin:12px 0;letter-spacing:-.8px}.auth-description{font-size:13px;line-height:1.8;color:var(--yb-ink-muted);margin-bottom:27px}
.auth-form label{display:block;margin:18px 0;font-size:13px;font-weight:600;color:var(--yb-ink-secondary)}.auth-form input{width:100%;display:block;border:1px solid var(--yb-border-strong);background:var(--yb-bg-surface);border-radius:var(--yb-radius-sm);padding:12px;margin-top:8px;font:inherit;font-weight:400;color:var(--yb-ink);min-width:0}.auth-form input::placeholder{color:#94a3b8;font-size:12px}.auth-form input:focus{outline:none;border-color:var(--yb-accent);box-shadow:0 0 0 3px var(--yb-accent-ring)}
.password-field{position:relative}.password-field input{padding-right:60px}.password-field button{position:absolute;right:8px;top:9px;padding:6px;border:0;background:none;color:var(--yb-ink-muted);font-size:12px}.auth-submit{width:100%;padding:13px;border:1px solid transparent;border-radius:var(--yb-radius-sm);background:var(--yb-accent);color:white;font-weight:650;margin-top:10px;font-size:14px;box-shadow:0 2px 4px var(--yb-accent-ring)}.auth-submit:hover:not(:disabled){background:var(--yb-accent-hover);box-shadow:0 4px 12px var(--yb-accent-ring)}.auth-submit:disabled{opacity:.6;cursor:wait}
.auth-switch{text-align:center;font-size:12px;color:var(--yb-ink-muted);margin-top:24px}.auth-switch a{color:var(--yb-accent);font-weight:600}.auth-switch a:hover{text-decoration:underline;text-underline-offset:3px}.auth-note{font-size:11px;color:var(--yb-ink-muted);line-height:1.8;margin-top:24px;padding-top:18px;border-top:1px solid var(--yb-border)}.auth-error,.auth-success{padding:12px;border-radius:var(--yb-radius-sm);font-size:13px;line-height:1.6}.auth-error{background:#fff0ed;color:#a84432}.auth-success{background:var(--yb-router-local-bg);color:var(--yb-router-local-ink)}
@media(max-width:1000px){.auth-story{padding:35px 8%}.auth-form{padding:26px}}
@media(max-width:800px){.auth-page{grid-template-columns:1fr}.auth-story{min-height:auto;padding:23px 25px}.story-copy,.auth-story small{display:none}.auth-form-wrap{padding:32px 20px}.auth-form h2{font-size:28px}}
</style>
